import CartContext from './cart-context';
import React,{useState} from 'react';

 const CartProvider=(props)=>{
    const [openCart, setOpenCart]=useState(false);
    const [cartItems, setCartItems] = useState([]);

    const totalQuantity = cartItems.reduce((acc, item) => acc + item.amount, 0);
    const totalPrice = cartItems.reduce((acc, item) => acc + item.amount * item.price, 0);

    const handleCart=()=>{
        setOpenCart(true);
       }

       const closeCart=()=>{
        setOpenCart(false);
       }

    // const updateCartItems = (item) => {
    //     const existingItemIndex = cartItems.findIndex((i) => i.id === item.id);
    
    //     if (existingItemIndex !== -1) {  
    //         const updatedItems = [...cartItems];
    //         updatedItems[existingItemIndex].amount += item.amount;
    //         setCartItems(updatedItems);
    //     } else {
    //         setCartItems((prevItems) => [...prevItems, { ...item }]);
    //     }
    // };
      // adding new logic   
      const updateCartItems = (item) => {
       
        const existingItem = cartItems.find((i) => i.name === item.name && i.size === item.size);
    
        if (existingItem) {  
           
            const updatedItems = cartItems.map((i) => {
                if (i.name === item.name && i.size === item.size) {
                    return { ...i, amount: i.amount + item.amount };
                }
                return i;
            });
            setCartItems(updatedItems);
        } else {
           
            setCartItems((prevItems) => [...prevItems, { ...item }]);
        }
    };
    
  const cartContext={
        items:cartItems,
        openCart,
        addItems:   updateCartItems,
        totalQuantity,
        totalPrice,
        handleCart,  // cart state
        closeCart,
  }

  return(
    <CartContext.Provider value={cartContext}>
        {props.children}
    </CartContext.Provider>

  )
 }
 export default CartProvider;
